#!/usr/bin/env python3
"""Q241 / Q245: docs/pose_rom_table.md from scripts/anatomy/q241/rom.py (the single source of the slider bounds and of their literature evidence).
tests/test_q241_rom.py and tests/test_q245_rom_evidence.py check the file is up to date."""
import sys
from collections import Counter
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
from rom import ROM, ROM_EVID, SOURCES, COUPLED, STATUS, spine_weights, status_text, ends, changed

REPO = Path(__file__).resolve().parents[3]
OUT = REPO / "docs/pose_rom_table.md"
GROUPS = [("Shoulder (glenohumeral + scapulothoracic, as measured clinically)", "shoulder_"), ("Elbow and forearm", ("elbow_", "forearm_")), ("Wrist", "wrist_"), ("Thumb", "thumb_"),
          ("Fingers (index to little)", "finger_"), ("Hip", "hip_"), ("Knee", "knee_"), ("Ankle and subtalar", "ankle_"), ("Toes", ("toe_", "toe1_")),
          ("Cervical spine / head", "cerv_"), ("Thoracic spine", "thor_"), ("Lumbar spine", "lumb_")]


def counts():
    c = Counter(e["st"] for _, _, e in ends())
    return c


def _cite(ids):
    return "; ".join(i for i in ids) if ids else "-"


def render() -> str:
    c = counts()
    nends = sum(c.values())
    nver = c["V_FT"] + c["V_AB"]
    L = ["# Normal range of motion used by the Pose panel (Q241, re-checked against the literature in Q245)\n"]
    L.append("Source of truth: `scripts/anatomy/q241/rom.py` (this file is generated by `scripts/anatomy/q241/make_rom_doc.py`; `tests/test_q241_rom.py` and `tests/test_q245_rom_evidence.py` fail when it is out of date). "
             "The per-end evidence is also embedded in the rig JSON of every page (`rom_meta`: Q241 value, soft limit, status code, number of sources read) - the viewer does not read it.\n")
    L.append("## How honest is this table (Q245)\n")
    L.append("Q241 quoted the AAOS / AMA values from memory. Q245 searched PubMed, Consensus and the web for measured series. **No web page could be fetched in the session (the fetch tool had no DNS), only PubMed records (abstracts, and the PMC full text of open-access papers) and "
             "search-engine summaries were readable**; the printed books (AAOS / Greene & Heckman, AMA Guides, Norkin & White, Kapandji, White & Panjabi) were never read. A bound is therefore labelled by what was actually seen:\n")
    for k in ("V_FT", "V_AB", "SEC", "AO", "AS", "DEF"):
        L.append("* **%s** - %d of %d range ends" % (STATUS[k], c[k], nends))
    L.append("")
    L.append("`verified from source` (%d ends) means the number was read in the paper's full text (Vairo 2012, Baumbach 2014) or in the PubMed abstract (Zwerus 2019, Kim 2014, Kouyoumdjian 2012, Cooney 1981, Edmondston 2012, Apti 2023); most of these rest on ONE sample (shown as 'single source'). "
             "`abstract only` means the paper exists and its abstract was read but the abstract has no number, so the earlier AAOS-style value is kept **unverified**. Paywalled tables (Boone & Azen 1979, Roaas & Andersson 1982, Soucie 2011, Mallon 1991, Youdas 1992 ...) were not opened; where a mean is quoted from them it comes from a search-engine summary of the page and is labelled `secondary snippet only`.\n" % nver)
    L.append("## Rule used for every bound (Q245)\n")
    L.append("* **Hard bound** (what the slider allows) = **mean + 1 SD** of the best adult sample whose mean and SD were read, rounded to a whole degree; if only a mean was read, that mean (the larger multi-sex sample when sources differ); if nothing was read, the earlier AAOS-style value (labelled). "
             "The same rule is applied on the negative side of a displayed value (e.g. extension, pronation, adduction).")
    L.append("* **Extended (soft) limit** = mean + 2 SD (97.5th percentile of a normal distribution), given only where an SD was read. The viewer does not use it yet (it needs a template change); it is in `rom_meta` of the rig JSON.")
    L.append("* **Passive** end-of-range values are preferred (the sliders pose a body, they do not model a muscle contraction); active ranges are 3-5 deg smaller (Zwerus 2019, Vairo 2012). Adult default 20-59 y, both sexes pooled; where sexes differ the difference is stated (women are usually more mobile: Soucie 2011, Barnes 2001, Zwerus 2019, Apti 2023 for lumbar flexion).")
    L.append("* **Caveat** - several series are young samples (Vairo 18-19 y athletic cadets, Apti 18-29 y), so mean + 1 SD is a generous 'upper normal' for ages 20-59 and a 60-year-old is well inside the bounds (Walker 1984, Macedo 2009, Youdas 1992, Lind 1989: motion falls with age, weakly for most peripheral joints). "
             "Nothing here is a clinical norm for a patient.")
    L.append("* If the model's own pose lies slightly outside the range (a hyperextended knee of a few degrees) it is shown as it is and can only be moved into the range. A slider shows the shaded normal range, a tick at the model's own pose and a faint line at 0.")
    L.append("* Zero conventions: neutral anatomical position (arms at the sides, palms forward, elbows / knees extended, feet at right angles to the shank); forearm rotation 0 = neutral (thumb forward), + = supination; the spine and head are measured from the posture as built (zero = the model's own spine).\n")
    L.append("## Ranges (degrees), one row per end\n")
    for title, pref in GROUPS:
        keys = [k for k in ROM if k.startswith(pref)]
        if not keys:
            continue
        L.append("### %s\n" % title)
        L.append("| displayed value / end | Q241 -> **Q245 hard bound** | extended (mean + 2 SD) | data read (mean +- SD or range; sample; method) | sources (see References) | status |\n|---|---|---|---|---|---|")
        for k in keys:
            lab = ROM_EVID[k]["label"]
            for w in ("lo", "hi"):
                e = ROM_EVID[k][w]
                parts = [p.strip() for p in lab.split(" / ")]
                nm = (parts[-1] if w == "lo" else parts[0]) if len(parts) > 1 else lab
                nm = nm.replace(" (+)", "").replace(" (-)", "").replace(" (0)", "")
                ch = "%g -> **%g**" % (e["old"], e["new"]) if e["old"] != e["new"] else "%g (unchanged)" % e["new"]
                L.append("| `%s` %s | %s | %s | %s | %s | %s |" % (k, nm, ch, ("%g" % e["soft"]) if e["soft"] is not None else "-", e["data"].replace("|", "/"), _cite(e["refs"]), status_text(e)))
        L.append("")
    L.append("## Old versus new (every bound that changed)\n")
    L.append("| range | end | Q241 | Q245 | change | status |\n|---|---|---|---|---|---|")
    for k, w, e in changed():
        parts = [p.strip() for p in ROM_EVID[k]["label"].split(" / ")]
        nm = (parts[-1] if w == "lo" else parts[0]) if len(parts) > 1 else ROM_EVID[k]["label"]
        nm = nm.replace(" (+)", "").replace(" (-)", "").replace(" (0)", "")
        L.append("| `%s` | %s | %g | %g | %+g | %s |" % (k, nm, e["old"], e["new"], e["new"] - e["old"], status_text(e)))
    L.append("")
    L.append("Largest corrections: cervical flexion / extension (45 / 45 -> 66 / 69, young goniometric sample, AAOS value was low) and cervical rotation (60 -> 81 per side), hip extension (30 -> 18), thumb CMC abduction (70 -> 42), hip internal rotation (45 -> 34), hip flexion (120 -> 132), ankle dorsiflexion (20 -> 29, but only 11 with the knee extended), ulnar deviation (30 -> 38). "
             "AAOS values that the literature read in Q245 supports within a few degrees are unchanged (elbow flexion 150, shoulder flexion 180, wrist flexion / radial deviation).\n")
    L.append("## Coupled motions that matter (and whether the Pose panel models them)\n")
    L.append("| coupling | data | sources | modelled |\n|---|---|---|---|")
    for what, data, refs, mod in COUPLED:
        L.append("| %s | %s | %s | %s |" % (what, data.replace("|", "/"), _cite(refs), "partly (see data)" if mod else "no"))
    L.append("")
    L.append("## Per-level split of the spinal ranges (ASSUMPTION, one value checked)\n")
    L.append("A regional slider (lumbar, thoracic, head / neck) moves every level joint of the region by a fixed share of the total. Equal shares, except: cervical rotation 50% at C1/C2 and the rest shared by C2-T1 "
             "(checked in Q245: Ishii 2004, 3D MRI, C1-C2 36.2 +- 4.5 deg and occiput-C1 1.7 +- 1.5 deg to each side, i.e. about 51% of the ~71 deg per side measured by Apti 2023); the occiput / C1 joint takes 20% of the cervical flexion-extension arc (White & Panjabi, book not read - not checked). "
             "Example shares: cervical flexion " + ", ".join("%.2f" % w for w in spine_weights("cervical", ["OCC", "C1", "C2", "C3", "C4", "C5", "C6", "C7"], "flex")) +
             " (occiput, C1 ... C7); cervical rotation " + ", ".join("%.2f" % w for w in spine_weights("cervical", ["OCC", "C1", "C2", "C3", "C4", "C5", "C6", "C7"], "rot")) + ".\n")
    L.append("## Joint mechanics in the Pose panel (what each slider moves)\n")
    L.append("* Joint centres and axes are computed from the page's OWN bones (`scripts/anatomy/q241/skeleton.py`, `rig.py`): hip and shoulder = sphere fit of the femoral / humeral head; elbow and knee = transepicondylar axis "
             "(sign from the radius / fibula, valid for any limb rotation); forearm = line radial head - ulnar head; wrist = centroid of the proximal carpals; fingers / toes = distal-end sphere / centroid of each bone; ankle = malleolar axis; "
             "subtalar = Inman's axis (42 deg above the horizontal, 23 deg medial to the foot axis) in the foot frame (literature axis, not fitted); spine = disc centres between the vertebral centroids; the fit errors are in `data/derived/Q241_rig_<page>.json`.")
    L.append("* Shoulder and hip: three angles in the order flexion (about the mediolateral axis), abduction (about the anteroposterior axis), rotation (about the bone's long axis), relative to the trunk / pelvis frame (intrinsic order; "
             "at 90 deg abduction flexion and rotation become the same motion - the usual Cardan singularity). Clavicle and scapula follow the shoulder with a fixed scapulohumeral rhythm (1/12 of the humeral elevation at the clavicle, 1/4 at the scapula, "
             "together 1/3 = a 2:1 glenohumeral : scapulothoracic ratio after Inman 1944, not re-read; the pin studies read in Q245 give 1.7:1 = 37% scapulothoracic, McClure 2001 - ASSUMPTION: linear, no 30 deg setting phase, upward rotation only). The patella follows 60% of the knee flexion angle (ASSUMPTION).")
    L.append("* Imaging-based pages: the bone meshes of all phalanges / metatarsals are merged into one mesh and cannot be separated reliably, so the fingers and toes are NOT articulated there (hand and foot move as one segment); "
             "Base and Combined pages have the individual bones and articulate thumb, index to little finger (MCP, PIP, DIP) and all toes.")
    L.append("* Not modelled: tibial rotation / screw-home, scapular and clavicular manual controls, finger abduction, thumb CMC axial rotation, carrying angle, jaw (TMJ), rib cage excursion, intercarpal motion, any soft-tissue collision or volume preservation.\n")
    L.append("## Joint-axis definitions versus the ISB recommendations (Wu et al. 2002, 2005)\n")
    L.append("**Status of this section:** the ISB recommendations (Wu 2002 J Biomech 35:543, doi 10.1016/s0021-9290(01)00222-6, PMID 11934426; Wu 2005 J Biomech 38:981, doi 10.1016/j.jbiomech.2004.05.042, PMID 15844264) were identified in PubMed and their abstracts read, "
             "but the recommendation texts could not be fetched; the comparison below is from the author's knowledge of them and from `rig.py` and must be checked against the originals before it is quoted. Both abstracts say the ISB defines, per joint, a local axis system in each segment and a joint coordinate system (JCS) of Grood-Suntay type.\n")
    L.append("| joint | Pose panel (`rig.py`) | ISB recommendation (as known, not re-read) | deviation / consequence for the ROM table |\n|---|---|---|---|")
    for row in [
        ("Hip", "pelvis frame from hip centres, sacrum, hip bones; femur frame hip centre - knee centre (transepicondylar midpoint) with the epicondylar line; order flexion (mediolateral) - abduction (AP) - rotation (femoral long axis, intrinsic)", "pelvis frame from the ASIS / PSIS landmarks; femur Y = knee centre to hip centre, Z through the epicondyles; JCS flexion about the pelvic Z, internal-external rotation about the femoral Y, floating axis for ab-adduction", "same joint centres and the same flexion-abduction-rotation order, so the numbers are comparable; the pelvis frame is built from bone meshes, not from ASIS / PSIS skin landmarks (the asymmetry report uses ASIS / PSIS); hip centre = head-sphere fit (ISB: regression or functional centre)"),
        ("Knee", "single hinge about the transepicondylar axis; no tibial rotation, no varus-valgus, patella 60% coupled", "3 DOF Grood-Suntay JCS (flexion, ab-adduction, internal-external rotation)", "2 DOF missing; the rotation data (Mossberg 1983: 35-44 deg total at 70-110 deg flexion) are therefore listed but not modelled"),
        ("Ankle", "talus is a segment: talocrural hinge through the malleolar tips (dorsiflexion), subtalar hinge on a fixed Inman axis (42 deg / 23 deg) for inversion; foot = one rigid segment", "ankle JCS between tibia/fibula and calcaneus: flexion about the tibial Z (malleolar line), internal-external rotation about the calcaneal long axis, inversion-eversion about the floating axis", "two stacked hinges instead of one 3-DOF JCS; the malleolar-tip axis is a good flexion axis but the true talocrural axis changes through the arc (Lundberg 1989a); the AAOS inversion / eversion values describe the foot, not the subtalar joint alone, so the subtalar range is probably overestimated (assumption kept)"),
        ("Spine", "regional (lumbar / thoracic / cervical) slider; one axis triple per region (trunk frame), angle shared over the levels by fixed weights; disc-centre joints", "per-level JCS between adjacent vertebrae: flexion-extension about Z, lateral bending about the floating axis, axial rotation about the inferior vertebra's Y; origin at the vertebral body", "no per-level JCS: only regional totals (clinical totals include the hips / pelvis for the lumbar goniometric values, see Apti 2023), coupling (Ishii 2004, Pearcy 1984) not modelled"),
        ("Shoulder", "humerus relative to the trunk, Cardan flexion - abduction - rotation (singular at 90 deg abduction); GH centre = humeral-head sphere; scapula / clavicle driven by a fixed 1/3 rhythm", "humerothoracic JCS: Y-X-Y' Euler sequence (plane of elevation, elevation, axial rotation; singular at the arm-down position), humerus Y = GH centre to epicondyle midpoint, Z through the epicondyles; separate SC / AC / GH recommendations", "different Euler sequence: the three angles equal ISB's only near the arm-down position; clinical ROM (flexion, abduction, rotation measured at 90 deg abduction by Vairo 2012) are position-defined and not ISB angles; fixed 1/3 scapular share vs 37% measured (McClure 2001) and no scapular tilt / external rotation (24 deg, 30 deg measured)"),
        ("Elbow / forearm", "flexion about the transepicondylar axis; forearm rotation about the line radial head - ulnar head", "elbow JCS: flexion about the humeral Z, forearm rotation about the ulnar Y, carrying angle about the floating axis", "pronation-supination axis radial head - ulnar head (anatomic) instead of the ulnar long axis (small tilt); carrying angle not modelled; forearm range measured at elbow 90 deg flexion (protocol) while the slider is free"),
        ("Wrist / hand", "wrist centre = centroid of the proximal carpals; flexion and deviation about forearm-frame axes; fingers: MCP / PIP / DIP flexion only; thumb CMC flexion + abduction, MCP, IP", "radius frame and third-metacarpal frame, flexion about the radial Z, radial-ulnar deviation about the floating axis; separate JCS for fingers (flexion, ab-adduction, axial) and thumb (CMC 3 DOF)", "centre of rotation differs (capitate region in ISB vs carpal centroid); finger abduction and thumb CMC axial rotation missing (Cooney 1981: 17 deg)"),
    ]:
        L.append("| %s | %s | %s | %s |" % row)
    L.append("")
    L.append("## Thresholds of the left / right pose comparison\n")
    L.append("The literature on side-to-side range-of-motion differences and what it does and does not justify for the 3-5 deg limb-joint and 8 deg long-axis tolerances is in `data/derived/Q241_pose_asymmetry.md`, section 2 (Q245).\n")
    L.append("## References (all cited ids; 'read' = what was actually available in Q245)\n")
    used = sorted({r for v in ROM_EVID.values() for w in ("lo", "hi") for r in v[w]["refs"]} | {r for _, _, refs, _ in COUPLED for r in refs} | {"Wu2002", "Wu2005", "Sadeghi2000", "Herzog1989", "Knutson2005", "Macedo2008", "Conte2009", "Gunal1996", "Allander1974", "Biaggi2021", "Myers2024", "McKay2017", "Boone1979", "Walker1984", "Elveru1988"})
    for i in used:
        cite, doi, pmid, how = SOURCES[i]
        L.append("* **%s** - %s%s%s. *Read:* %s." % (i, cite, ("; doi:%s" % doi) if doi else "", ("; PMID %s" % pmid) if pmid else "", how))
    L.append("")
    return "\n".join(L) + "\n"


if __name__ == "__main__":
    OUT.write_text(render(), encoding="utf-8")
    print("wrote", OUT)
